tracks = {}
next_id = 1
def iou(a, b):
    x1, y1 = max(a[0], b[0]), max(a[1], b[1])
    x2, y2 = min(a[2], b[2]), min(a[3], b[3])
    intersection = max(0.0, x2-x1) * max(0.0, y2-y1)
    area_a = max(0.0, a[2]-a[0]) * max(0.0, a[3]-a[1])
    area_b = max(0.0, b[2]-b[0]) * max(0.0, b[3]-b[1])
    union = area_a + area_b - intersection
    return intersection / union if union > 0 else 0.0
def process(detections, clock):
    global next_id
    candidates = sorted(((iou(track['box'], det['box']), tid, j) for tid, track in tracks.items() for j, det in enumerate(detections)), reverse=True)
    used_ids, used_indices, assignment = set(), set(), {}
    for overlap, tid, j in candidates:
        if overlap < 0.3: break
        if tid not in used_ids and j not in used_indices:
            assignment[j] = tid
            used_ids.add(tid)
            used_indices.add(j)
    for tid in list(tracks):
        if tid not in used_ids:
            tracks[tid]['missed'] += 1
            if tracks[tid]['missed'] > 30: del tracks[tid]
    current = []
    for j, det in enumerate(detections):
        if j in assignment: tid = assignment[j]
        else:
            tid = next_id
            next_id += 1
        tracks[tid] = {'box': det['box'], 'missed': 0}
        current.append({**det, 'id': tid})
    return current  # Never emit retained-but-missed tracks as current people.

import math
states = {}
video_start_s = None
def midpoint(a, b): return ((a[0]+b[0])/2.0, (a[1]+b[1])/2.0)
def process(persons, clock):
    global video_start_s
    t = clock['timestamp_s']
    if video_start_s is None: video_start_s = t
    present_ids = {p['id'] for p in persons}
    # A missed observation interrupts a continuous posture hold; retained tracker IDs are not observations.
    for tid, state in states.items():
        if tid not in present_ids:
            state['hold_start'] = None
            state['prev_hip'] = None
            state['prev_t'] = None
            state['drop_t'] = None
            state['fallen'] = False
    result = []
    for person in persons:
        tid = person['id']
        state = states.setdefault(tid, {'floor_y': None, 'prev_hip': None, 'prev_t': None, 'drop_t': None, 'hold_start': None, 'fallen': False})
        k = person['keypoints']
        pose_valid = all(k[j][2] >= 0.5 for j in (5, 6, 11, 12))
        hip = None
        torso = None
        angle = None
        if pose_valid:
            shoulder = midpoint(k[5], k[6])
            hip = midpoint(k[11], k[12])
            dx, dy = hip[0]-shoulder[0], hip[1]-shoulder[1]
            torso = math.hypot(dx, dy)
            if torso > 0: angle = math.degrees(math.atan2(abs(dx), abs(dy)+1e-6))
        if t - video_start_s <= 3 and angle is not None and angle <= 30:
            visible_ankles = [k[j][1] for j in (15, 16) if k[j][2] >= 0.5]
            if visible_ankles:
                lowest_y = max(visible_ankles)  # Image y grows downwards.
                state['floor_y'] = lowest_y if state['floor_y'] is None else max(state['floor_y'], lowest_y)
        rapid_drop = False
        if hip is not None and torso is not None and torso > 0 and state['prev_hip'] is not None and state['prev_t'] is not None:
            dt = t - state['prev_t']
            if dt > 0:
                speed_torso_lengths_per_s = (hip[1] - state['prev_hip'][1]) / (torso * dt)
                rapid_drop = speed_torso_lengths_per_s > 1.2
        if rapid_drop: state['drop_t'] = t
        if state['drop_t'] is not None and t - state['drop_t'] > 1.5:
            state['drop_t'] = None
            state['hold_start'] = None
        near_floor = (hip is not None and torso is not None and torso > 0 and state['floor_y'] is not None and (state['floor_y'] - hip[1]) / torso < 0.5)
        posture = angle is not None and angle > 60 and near_floor
        if state['drop_t'] is not None and posture and t - state['drop_t'] <= 1.5 and state['hold_start'] is None:
            state['hold_start'] = t
        elif state['hold_start'] is not None and not posture:
            state['hold_start'] = None
            state['drop_t'] = None
            state['fallen'] = False
        fall_event = False
        if state['hold_start'] is not None and posture and t - state['hold_start'] >= 3 and not state['fallen']:
            state['fallen'] = True
            fall_event = True
        if hip is not None and torso is not None and torso > 0:
            state['prev_hip'], state['prev_t'] = hip, t
        else:
            state['prev_hip'], state['prev_t'] = None, None
        status = 'floor_uncalibrated' if state['floor_y'] is None else ('fallen' if state['fallen'] else 'fall_posture_pending' if state['hold_start'] is not None else 'observing')
        result.append({**person, 'fallen': state['fallen'], 'fall_event': fall_event, 'fall_status': status})
    return {'frame_index': clock['frame_index'], 'timestamp_s': t, 'persons': result, 'fall_events': [{'id': p['id'], 'timestamp_s': t} for p in result if p['fall_event']]}

import json
from pathlib import Path
path = Path('/home/dread/pipegen_out/keypoints.jsonl')
path.parent.mkdir(parents=True, exist_ok=True)
stream = path.open('w', encoding='utf-8')
def process(result):
    record = {'frame_index': result['frame_index'], 'timestamp_s': result['timestamp_s'], 'persons': [{'id': p['id'], 'box': p['box'], 'keypoints': p['keypoints'], 'score': p['score'], 'fallen': p['fallen'], 'fall_event': p['fall_event'], 'fall_status': p['fall_status']} for p in result['persons']]}
    stream.write(json.dumps(record, allow_nan=False) + '\n')
    stream.flush()
def close(): stream.close()

import cv2
SKELETON = [(15,13),(13,11),(16,14),(14,12),(11,12),(5,11),(6,12),(5,6),(5,7),(6,8),(7,9),(8,10),(1,2),(0,1),(0,2),(1,3),(2,4),(3,5),(4,6)]
def process(pixelated_frame, result):
    image = pixelated_frame.copy()
    for person in result['persons']:
        color = (0,0,255) if person['fallen'] else (0,255,0)
        x1,y1,x2,y2 = map(int, person['box'])
        cv2.rectangle(image, (x1,y1), (x2,y2), color, 2)
        cv2.putText(image, f"ID {person['id']} {'FALL' if person['fallen'] else person['fall_status']}", (x1,max(0,y1-8)), cv2.FONT_HERSHEY_SIMPLEX, 0.55, color, 2)
        k = person['keypoints']
        for a,b in SKELETON:
            if k[a][2] >= 0.5 and k[b][2] >= 0.5:
                cv2.line(image, (int(k[a][0]),int(k[a][1])), (int(k[b][0]),int(k[b][1])), (255,200,0), 2)
        for x,y,v in k:
            if v >= 0.5: cv2.circle(image, (int(x),int(y)), 3, (0,165,255), -1)
    cv2.imshow('Human pose and fall detection', image)
    cv2.waitKey(1)
